/**
 * Environment detection and safe global access.
 *
 * @remarks
 * Importing this module must never touch `window` or `indexedDB` at module scope —
 * the package has to be importable in Node, in SSR frameworks and inside Web
 * Workers. Every accessor here is a function that feature-detects on call.
 */

/** Structural view of `globalThis` for defensive lookups. */
type GlobalRecord = Record<string, unknown>;

/** Read a property from `globalThis` without ever throwing. */
export function getGlobal(key: string): unknown {
  try {
    return (globalThis as unknown as GlobalRecord)[key];
  } catch {
    return undefined;
  }
}

/**
 * Read a property from an arbitrary object without triggering hostile getters.
 *
 * @param target - the object or function to read from
 * @param key - the property name
 * @returns the value, or `undefined` if reading threw
 *
 * @remarks
 * A function is a valid target. Static members live on constructors and `typeof`
 * reports those as `'function'`, so rejecting anything that is not a plain object
 * made every static lookup return `undefined` — including
 * `URL.createObjectURL`, which the diagnostics download depends on.
 *
 * @example
 * ```ts
 * safeGet(hostileProxy, 'message'); // undefined instead of throwing
 * safeGet(URL, 'createObjectURL'); // the static method, not undefined
 * ```
 */
export function safeGet(target: unknown, key: string): unknown {
  if (target === null || (typeof target !== 'object' && typeof target !== 'function')) {
    return undefined;
  }
  try {
    return (target as GlobalRecord)[key];
  } catch {
    return undefined;
  }
}

/** The `window` object, or `undefined` in Node/SSR/workers. */
export function getWindow(): (Window & typeof globalThis) | undefined {
  const w = getGlobal('window');
  if (w === null || typeof w !== 'object') return undefined;
  return w as Window & typeof globalThis;
}

/** The `document` object, or `undefined` outside a DOM environment. */
export function getDocument(): Document | undefined {
  const d = getGlobal('document');
  if (d === null || typeof d !== 'object') return undefined;
  return d as Document;
}

/** The `navigator` object, or `undefined` in Node. */
export function getNavigator(): Navigator | undefined {
  const n = getGlobal('navigator');
  if (n === null || typeof n !== 'object') return undefined;
  return n as Navigator;
}

/**
 * The worker/`self` scope, when it is genuinely a worker-like global.
 *
 * @remarks
 * Returns `undefined` when `window` exists, so callers can write
 * "browser first, worker fallback" logic without double-installing handlers.
 */
export function getWorkerScope():
  | (typeof globalThis & { onerror?: unknown; addEventListener?: unknown })
  | undefined {
  if (getWindow() !== undefined) return undefined;
  const s = getGlobal('self');
  if (s === null || typeof s !== 'object') return undefined;
  return s as typeof globalThis & { onerror?: unknown; addEventListener?: unknown };
}

/**
 * Whether a DOM-capable browser environment is present.
 *
 * @example
 * ```ts
 * if (isBrowser()) installDiagnosticsExportShortcut();
 * ```
 */
export function isBrowser(): boolean {
  return getWindow() !== undefined && getDocument() !== undefined;
}

/**
 * The best available event target for global listeners.
 *
 * @returns `window` in a browser, `self` in a worker, otherwise `undefined`.
 */
export function getEventTarget(): EventTarget | undefined {
  const w = getWindow();
  if (w !== undefined) return w;
  const s = getWorkerScope();
  if (s !== undefined && typeof s.addEventListener === 'function') {
    return s as unknown as EventTarget;
  }
  return undefined;
}

/** Current time in milliseconds. Wrapped so it can be stubbed in tests. */
export function now(): number {
  return Date.now();
}

/**
 * Whether the browser reports itself as online.
 *
 * @remarks
 * Returns `true` when unknown, so that a missing `navigator.onLine` never
 * suppresses an upload attempt.
 */
export function isOnline(): boolean {
  const n = getNavigator();
  if (n === undefined) return true;
  const value = safeGet(n, 'onLine');
  return typeof value === 'boolean' ? value : true;
}

/** Read `document.visibilityState`, if available. */
export function getVisibilityState(): string | undefined {
  const d = getDocument();
  if (d === undefined) return undefined;
  const value = safeGet(d, 'visibilityState');
  return typeof value === 'string' ? value : undefined;
}

/** Read `navigator.userAgent`. */
export function getUserAgent(): string | undefined {
  const n = getNavigator();
  if (n === undefined) return undefined;
  const value = safeGet(n, 'userAgent');
  return typeof value === 'string' ? value : undefined;
}

/** Read `navigator.platform`, falling back to `navigator.userAgentData.platform`. */
export function getPlatform(): string | undefined {
  const n = getNavigator();
  if (n === undefined) return undefined;
  const direct = safeGet(n, 'platform');
  if (typeof direct === 'string' && direct.length > 0) return direct;
  const uaData = safeGet(n, 'userAgentData');
  const fromUaData = safeGet(uaData, 'platform');
  return typeof fromUaData === 'string' ? fromUaData : undefined;
}

/** Read the inner viewport size as `"<width>x<height>"`. */
export function getViewport(): string | undefined {
  const w = getWindow();
  if (w === undefined) return undefined;
  const width = safeGet(w, 'innerWidth');
  const height = safeGet(w, 'innerHeight');
  if (typeof width !== 'number' || typeof height !== 'number') return undefined;
  return `${String(width)}x${String(height)}`;
}

/** Read `location.href` without throwing in exotic contexts. */
export function getLocationHref(): string | undefined {
  const w = getWindow();
  if (w === undefined) return undefined;
  const loc = safeGet(w, 'location');
  const href = safeGet(loc, 'href');
  return typeof href === 'string' ? href : undefined;
}

/**
 * Read `import.meta.env` when the bundler provides it.
 *
 * @remarks
 * This is the **only** place in the library that touches `import.meta.env`.
 * `initTelemetry` never reads build-time env directly; callers opt in through
 * {@link fromEnv}, which keeps the core bundler-agnostic.
 */
function readImportMetaEnv(): Record<string, unknown> | undefined {
  try {
    // `.env` is read as a *property* of `import.meta` rather than by binding
    // `import.meta` to a local first. Webpack only supports property access and
    // otherwise emits "Critical dependency: Accessing import.meta directly is
    // unsupported", which every webpack consumer of the published ESM build would
    // see. The cast is erased at compile time, so the emitted code is exactly
    // `import.meta.env`, and behaviour is unchanged: `undefined` wherever a
    // bundler did not define it.
    return (import.meta as unknown as { env?: Record<string, unknown> }).env;
  } catch {
    return undefined;
  }
}

/** Read `process.env` when running under Node or a Node-compatible bundler. */
function readProcessEnv(): Record<string, string | undefined> | undefined {
  try {
    const proc = (globalThis as unknown as GlobalRecord)['process'];
    const env = safeGet(proc, 'env');
    if (env === null || typeof env !== 'object') return undefined;
    return env as Record<string, string | undefined>;
  } catch {
    return undefined;
  }
}

/** Default bundler prefixes tried by {@link fromEnv}, in priority order. */
export const DEFAULT_ENV_PREFIXES: readonly string[] = ['VITE_', 'NEXT_PUBLIC_', 'REACT_APP_'];

/** The subset of `TelemetryOptions` that {@link fromEnv} can populate. */
export interface EnvOptions {
  readonly appName?: string;
  readonly appVersion?: string;
  readonly buildId?: string;
  readonly environment?: string;
  readonly enabled?: boolean;
  readonly dbPrefix?: string;
  /** `TELEMETRY_OPEN_TIMEOUT_MS` — milliseconds to wait for an IndexedDB open. */
  readonly openTimeoutMs?: number;

  /** `ERROR_TRACKING_ENABLED`. */
  readonly errorsEnabled?: boolean;
  /** `ERROR_TRACKING_RETENTION_DAYS` — days; `0` disables age-based deletion. */
  readonly errorsRetentionDays?: number;
  /** `ERROR_TRACKING_MAX_RECORDS` — rows retained. */
  readonly errorsMaxRecords?: number;
  /** `ERROR_TRACKING_MAX_PAYLOAD_BYTES` — UTF-8 byte budget per record. */
  readonly errorsMaxPayloadBytes?: number;
  /** `ERROR_TRACKING_MAX_EVENTS_PER_MINUTE` — `0` disables the limiter. */
  readonly errorsMaxEventsPerMinute?: number;

  /** `LOG_PERSIST_ENABLED`. */
  readonly logsEnabled?: boolean;
  /** `LOG_LEVEL` — the **console** level applied at initialisation. */
  readonly consoleLevel?: string;
  /** `LOG_PERSIST_LEVEL` — the **persist** level. Falls back to `LOG_LEVEL` when empty. */
  readonly persistLevel?: string;
  /** `TELEMETRY_LOG_LEVEL` — legacy name for the persist level. */
  readonly logLevel?: string;
  /** `LOG_PERSIST_RETENTION_DAYS` — days; `0` disables age-based deletion. */
  readonly logsRetentionDays?: number;
  /** `LOG_PERSIST_MAX_RECORDS` — rows retained. */
  readonly logsMaxRecords?: number;
  /** `LOG_PERSIST_MAX_PAYLOAD_BYTES` — UTF-8 byte budget per record. */
  readonly logsMaxPayloadBytes?: number;
  /** `LOG_PERSIST_MAX_LOGS_PER_MINUTE` — `0` disables the limiter. */
  readonly logsMaxLogsPerMinute?: number;
  /** `LOG_PERSIST_WRITE_FLUSH_MS` — upper bound in milliseconds on a buffered log. */
  readonly logsWriteFlushMs?: number;
  /** `LOG_PERSIST_WRITE_BATCH_SIZE` — buffered entries that trigger a write. */
  readonly logsWriteBatchSize?: number;

  /** `TELEMETRY_REST_ENABLED`. */
  readonly restEnabled?: boolean;
  /** `ERROR_TRACKING_REST_URL`. */
  readonly errorsUrl?: string;
  /** `LOG_TRACKING_REST_URL`. */
  readonly logsUrl?: string;
  /** `TELEMETRY_SYNC_INTERVAL_MS` — delay between flush runs, in milliseconds. */
  readonly restIntervalMs?: number;
  /** `TELEMETRY_SYNC_BATCH_SIZE` — records per request. */
  readonly restBatchSize?: number;
}

/** Look up `NAME` for each prefix, returning the first non-empty match. */
function lookupEnv(
  key: string,
  prefixes: readonly string[],
  meta: Record<string, unknown> | undefined,
  proc: Record<string, string | undefined> | undefined,
): string | undefined {
  for (const prefix of prefixes) {
    const full = `${prefix}${key}`;
    const fromMeta = meta === undefined ? undefined : safeGet(meta, full);
    if (typeof fromMeta === 'string' && fromMeta.length > 0) return fromMeta;
    const fromProc = proc === undefined ? undefined : proc[full];
    if (typeof fromProc === 'string' && fromProc.length > 0) return fromProc;
  }
  return undefined;
}

/** Parse a boolean-ish env string (`true`/`1`/`yes`/`on` and negatives). */
function parseBool(value: string | undefined): boolean | undefined {
  if (value === undefined) return undefined;
  const v = value.trim().toLowerCase();
  if (v === 'true' || v === '1' || v === 'yes' || v === 'on') return true;
  if (v === 'false' || v === '0' || v === 'no' || v === 'off') return false;
  return undefined;
}

/**
 * Parse a numeric env string.
 *
 * @remarks
 * An empty string, a non-number or a negative value yields `undefined`, so the
 * option falls back to its default rather than being applied. Whether `0` is
 * meaningful is decided per option by `resolveOptions`, not here: `retentionDays`
 * and the rate limiters treat `0` as "disabled", while `maxRecords` and
 * `maxPayloadBytes` reject it as a mistake.
 */
function parseNumber(
  value: string | undefined,
  options: { integer?: boolean } = {},
): number | undefined {
  if (value === undefined) return undefined;
  const trimmed = value.trim();
  if (trimmed === '') return undefined;
  const parsed = Number(trimmed);
  if (!Number.isFinite(parsed) || parsed < 0) return undefined;
  return options.integer === true ? Math.floor(parsed) : parsed;
}

/** Read the first present name from a primary name plus legacy aliases. */
function lookupNamed(
  primary: string,
  legacy: readonly string[],
  prefixes: readonly string[],
  meta: Record<string, unknown> | undefined,
  proc: Record<string, string | undefined> | undefined,
): string | undefined {
  const direct = lookupEnv(primary, prefixes, meta, proc);
  if (direct !== undefined) return direct;
  for (const name of legacy) {
    const value = lookupEnv(name, prefixes, meta, proc);
    if (value !== undefined) return value;
  }
  return undefined;
}

/**
 * Build telemetry options from build-time environment variables.
 *
 * @param prefix - one prefix, or a list, to search. Defaults to
 * `['VITE_', 'NEXT_PUBLIC_', 'REACT_APP_']`.
 * @returns a partial options object; every field is omitted unless the matching
 * environment variable was present, non-empty and parseable.
 *
 * @remarks
 * Every variable is optional, and the prefix is supplied by the caller so the
 * same names work in any bundler. Variables are shown below without their prefix.
 *
 * **Application identity**
 *
 * | Variable                   | Option                | Default     |
 * | -------------------------- | --------------------- | ----------- |
 * | `APP_NAME`                 | `appName`             | none        |
 * | `APP_VERSION`              | `appVersion`          | none        |
 * | `BUILD_ID`                 | `buildId`             | none        |
 * | `APP_ENV`, `ENVIRONMENT`   | `environment`         | none        |
 * | `TELEMETRY_ENABLED`        | `enabled`             | `true`      |
 * | `TELEMETRY_DB_PREFIX`      | `dbPrefix`            | `rm-logvault` |
 * | `TELEMETRY_OPEN_TIMEOUT_MS` | `openTimeoutMs`      | `5000`      |
 *
 * **Errors — their own IndexedDB store**
 *
 * | Variable                                | Option                      | Unit                          | Default   |
 * | --------------------------------------- | --------------------------- | ----------------------------- | --------- |
 * | `ERROR_TRACKING_ENABLED`                | `errors.enabled`            | boolean                       | `true`    |
 * | `ERROR_TRACKING_RETENTION_DAYS`         | `errors.retentionDays`      | days, `0` = no age deletion   | `7`       |
 * | `ERROR_TRACKING_MAX_RECORDS`            | `errors.maxRecords`         | rows                          | `500`     |
 * | `ERROR_TRACKING_MAX_PAYLOAD_BYTES`      | `errors.maxPayloadBytes`    | UTF-8 bytes                   | `16384`   |
 * | `ERROR_TRACKING_MAX_EVENTS_PER_MINUTE`  | `errors.maxEventsPerMinute` | events per 60 s, `0` = off    | `120`     |
 *
 * **Logs — their own IndexedDB store**
 *
 * | Variable                          | Option                    | Unit                        | Default |
 * | --------------------------------- | ------------------------- | --------------------------- | ------- |
 * | `LOG_PERSIST_ENABLED`             | `logs.enabled`            | boolean                     | `true`  |
 * | `LOG_LEVEL`                       | `logs.consoleLevel`       | level                       | unchanged |
 * | `LOG_PERSIST_LEVEL`               | `logs.level`              | level; empty inherits `LOG_LEVEL` | `warn` |
 * | `LOG_PERSIST_RETENTION_DAYS`      | `logs.retentionDays`      | days, `0` = no age deletion | `3`     |
 * | `LOG_PERSIST_MAX_RECORDS`         | `logs.maxRecords`         | rows                        | `2000`  |
 * | `LOG_PERSIST_MAX_PAYLOAD_BYTES`   | `logs.maxPayloadBytes`    | UTF-8 bytes                 | `4096`  |
 * | `LOG_PERSIST_MAX_LOGS_PER_MINUTE` | `logs.maxLogsPerMinute`   | logs per 60 s, `0` = off    | `600`   |
 * | `LOG_PERSIST_WRITE_FLUSH_MS`      | `logs.writeFlushMs`       | milliseconds                | `1000`  |
 * | `LOG_PERSIST_WRITE_BATCH_SIZE`    | `logs.writeBatchSize`     | entries per write           | `50`    |
 *
 * **REST upload** — errors and logs may post to different endpoints, and IndexedDB
 * stays the offline outbox either way.
 *
 * | Variable                      | Option              | Unit                    | Default        |
 * | ----------------------------- | ------------------- | ----------------------- | -------------- |
 * | `TELEMETRY_REST_ENABLED`      | `rest.enabled`      | boolean                 | `true` when a URL is set |
 * | `ERROR_TRACKING_REST_URL`     | `rest.errorsUrl`    | absolute `http(s)` or a path | none     |
 * | `LOG_TRACKING_REST_URL`       | `rest.logsUrl`      | absolute `http(s)` or a path | none     |
 * | `TELEMETRY_SYNC_INTERVAL_MS`  | `rest.intervalMs`   | milliseconds            | `30000`        |
 * | `TELEMETRY_SYNC_BATCH_SIZE`   | `rest.batchSize`    | records per request     | `50`           |
 *
 * **Legacy aliases**, still read so an earlier configuration keeps working. The
 * specific names above win when both are set: `TELEMETRY_ERRORS_ENABLED`,
 * `TELEMETRY_LOGS_ENABLED`, `TELEMETRY_PERSIST_LEVEL`, `TELEMETRY_LOG_LEVEL`
 * (persist level only — it never sets the console level), `TELEMETRY_ERRORS_URL`,
 * `TELEMETRY_LOGS_URL`.
 *
 * A value that cannot be parsed is ignored, exactly as an invalid option is, so a
 * typo falls back to the default instead of silently changing behaviour.
 *
 * Reading never throws, even when both `import.meta.env` and `process.env` are
 * absent.
 *
 * @example
 * ```ts
 * import { initTelemetry, fromEnv } from '@codewithrajat/rm-logvault';
 *
 * // Apply the whole environment: `options.env` is what `resolveOptions` consults.
 * initTelemetry({ env: true });
 * initTelemetry({ env: 'NEXT_PUBLIC_' });
 *
 * // `fromEnv()` reads the values. Its fields are FLAT, so place the nested ones
 * // yourself — spreading it carries only the six top-level identity fields.
 * const env = fromEnv();
 * initTelemetry({ appName: env.appName, errors: { maxRecords: env.errorsMaxRecords } });
 * ```
 */
export function fromEnv(prefix: string | readonly string[] = DEFAULT_ENV_PREFIXES): EnvOptions {
  const prefixes =
    typeof prefix === 'string' ? [prefix] : prefix.length > 0 ? prefix : DEFAULT_ENV_PREFIXES;

  let meta: Record<string, unknown> | undefined;
  let proc: Record<string, string | undefined> | undefined;
  try {
    meta = readImportMetaEnv();
    proc = readProcessEnv();
  } catch {
    // Both readers are individually guarded; this is belt-and-braces.
  }

  const out: {
    -readonly [K in keyof EnvOptions]: EnvOptions[K];
  } = {};

  const set = <K extends keyof EnvOptions>(key: K, value: EnvOptions[K] | undefined): void => {
    if (value !== undefined) out[key] = value;
  };

  // ---- identity -----------------------------------------------------------
  set('appName', lookupEnv('APP_NAME', prefixes, meta, proc));
  set('appVersion', lookupEnv('APP_VERSION', prefixes, meta, proc));
  set('buildId', lookupEnv('BUILD_ID', prefixes, meta, proc));
  set(
    'environment',
    lookupEnv('APP_ENV', prefixes, meta, proc) ?? lookupEnv('ENVIRONMENT', prefixes, meta, proc),
  );
  set('enabled', parseBool(lookupEnv('TELEMETRY_ENABLED', prefixes, meta, proc)));
  set('dbPrefix', lookupEnv('TELEMETRY_DB_PREFIX', prefixes, meta, proc));
  set(
    'openTimeoutMs',
    parseNumber(lookupEnv('TELEMETRY_OPEN_TIMEOUT_MS', prefixes, meta, proc), { integer: true }),
  );

  // ---- errors -------------------------------------------------------------
  set(
    'errorsEnabled',
    parseBool(
      lookupNamed('ERROR_TRACKING_ENABLED', ['TELEMETRY_ERRORS_ENABLED'], prefixes, meta, proc),
    ),
  );
  set(
    'errorsRetentionDays',
    parseNumber(lookupEnv('ERROR_TRACKING_RETENTION_DAYS', prefixes, meta, proc)),
  );
  set(
    'errorsMaxRecords',
    parseNumber(lookupEnv('ERROR_TRACKING_MAX_RECORDS', prefixes, meta, proc), { integer: true }),
  );
  set(
    'errorsMaxPayloadBytes',
    parseNumber(lookupEnv('ERROR_TRACKING_MAX_PAYLOAD_BYTES', prefixes, meta, proc), {
      integer: true,
    }),
  );
  set(
    'errorsMaxEventsPerMinute',
    parseNumber(lookupEnv('ERROR_TRACKING_MAX_EVENTS_PER_MINUTE', prefixes, meta, proc), {
      integer: true,
    }),
  );

  // ---- logs ---------------------------------------------------------------
  const consoleLevel = lookupEnv('LOG_LEVEL', prefixes, meta, proc);
  const persistLevel = lookupNamed(
    'LOG_PERSIST_LEVEL',
    ['TELEMETRY_PERSIST_LEVEL'],
    prefixes,
    meta,
    proc,
  );
  set(
    'logsEnabled',
    parseBool(lookupNamed('LOG_PERSIST_ENABLED', ['TELEMETRY_LOGS_ENABLED'], prefixes, meta, proc)),
  );
  set('consoleLevel', consoleLevel);
  set('persistLevel', persistLevel);
  // The legacy name fed the persist level; it deliberately does not touch the
  // console level, so an existing deployment's console output is unchanged.
  set('logLevel', lookupEnv('TELEMETRY_LOG_LEVEL', prefixes, meta, proc));
  set(
    'logsRetentionDays',
    parseNumber(lookupEnv('LOG_PERSIST_RETENTION_DAYS', prefixes, meta, proc)),
  );
  set(
    'logsMaxRecords',
    parseNumber(lookupEnv('LOG_PERSIST_MAX_RECORDS', prefixes, meta, proc), { integer: true }),
  );
  set(
    'logsMaxPayloadBytes',
    parseNumber(lookupEnv('LOG_PERSIST_MAX_PAYLOAD_BYTES', prefixes, meta, proc), {
      integer: true,
    }),
  );
  set(
    'logsMaxLogsPerMinute',
    parseNumber(lookupEnv('LOG_PERSIST_MAX_LOGS_PER_MINUTE', prefixes, meta, proc), {
      integer: true,
    }),
  );
  set(
    'logsWriteFlushMs',
    parseNumber(lookupEnv('LOG_PERSIST_WRITE_FLUSH_MS', prefixes, meta, proc), { integer: true }),
  );
  set(
    'logsWriteBatchSize',
    parseNumber(lookupEnv('LOG_PERSIST_WRITE_BATCH_SIZE', prefixes, meta, proc), { integer: true }),
  );

  // ---- rest ---------------------------------------------------------------
  set('restEnabled', parseBool(lookupEnv('TELEMETRY_REST_ENABLED', prefixes, meta, proc)));
  set(
    'errorsUrl',
    lookupNamed('ERROR_TRACKING_REST_URL', ['TELEMETRY_ERRORS_URL'], prefixes, meta, proc),
  );
  set(
    'logsUrl',
    lookupNamed('LOG_TRACKING_REST_URL', ['TELEMETRY_LOGS_URL'], prefixes, meta, proc),
  );
  set(
    'restIntervalMs',
    parseNumber(lookupEnv('TELEMETRY_SYNC_INTERVAL_MS', prefixes, meta, proc), { integer: true }),
  );
  set(
    'restBatchSize',
    parseNumber(lookupEnv('TELEMETRY_SYNC_BATCH_SIZE', prefixes, meta, proc), { integer: true }),
  );

  return out;
}
