/**
 * The shipped `fetch` implementation of the HTTP client contract.
 *
 * @remarks
 * Lives on its own subpath (`@codewithrajat/rm-logvault/http`) so an
 * application that uses an axios or ky client pays nothing for this one, and so the
 * core entry keeps its bundle budget (I-8).
 *
 * It is written to the same rules as the rest of the package: every interceptor
 * callback is contained, the abort timer is always cleared, and a failure surfaces
 * as a real `HttpError` carrying only allow-listed request metadata. Unlike the
 * telemetry pipeline it **does** read response bodies — that is the point of an
 * HTTP client — but it never copies them into an error context.
 *
 * @packageDocumentation
 */

import { reportInternalFailure } from '../core/internal.js';
import type {
  HttpClient,
  HttpClientOptions,
  HttpError,
  HttpInterceptor,
  HttpMethod,
  HttpRequest,
  HttpResponse,
} from './http.js';
import {
  buildHttpErrorContext,
  DEFAULT_HTTP_RETRY_DELAY_MS,
  DEFAULT_HTTP_TIMEOUT_MS,
  isRetryableStatus,
  resolveRequestUrl,
} from './http.js';

/** Resolve a `fetch` implementation defensively, per request. */
function resolveFetch(override: typeof fetch | undefined): typeof fetch | undefined {
  if (override !== undefined) return override;
  try {
    const candidate: unknown = Reflect.get(globalThis, 'fetch');
    return typeof candidate === 'function' ? (candidate as typeof fetch) : undefined;
  } catch {
    return undefined;
  }
}

/** Whether a content type describes JSON. */
function looksLikeJson(contentType: string): boolean {
  return /^application\/(?:[\w.+-]+\+)?json\b/i.test(contentType);
}

/** Copy a `Headers`-like object into a plain record, never throwing. */
function readHeaders(headers: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  try {
    const forEach: unknown = Reflect.get(headers as object, 'forEach');
    if (typeof forEach !== 'function') return out;
    Reflect.apply(forEach, headers, [
      (value: unknown, key: unknown): void => {
        if (typeof key === 'string' && typeof value === 'string') out[key.toLowerCase()] = value;
      },
    ]);
  } catch {
    // A hostile Headers object yields an empty map rather than an exception.
  }
  return out;
}

/** Build a normalised request, guarding every field a caller could have botched. */
async function applyInterceptors(
  initial: HttpRequest,
  interceptors: readonly HttpInterceptor[],
): Promise<HttpRequest | null> {
  let current = initial;
  for (const interceptor of interceptors) {
    const hook = interceptor.onRequest;
    if (typeof hook !== 'function') continue;
    try {
      const next = await hook(current);
      if (next === null) return null;
      if (next !== undefined && typeof next === 'object') current = next;
    } catch (error) {
      reportInternalFailure('http-interceptor-request', error);
      throw error;
    }
  }
  return current;
}

/** Decode a response body according to `readAs`. */
async function readBody(
  response: Response,
  readAs: NonNullable<HttpClientOptions['readAs']>,
): Promise<unknown> {
  try {
    if (readAs === 'none') return undefined;
    if (readAs === 'json') return await response.json();
    if (readAs === 'arrayBuffer') return await response.arrayBuffer();
    if (readAs === 'blob') return await response.blob();
    if (readAs === 'text') return await response.text();
    // 'auto'
    const contentType = response.headers.get('content-type') ?? '';
    return looksLikeJson(contentType) ? await response.json() : await response.text();
  } catch (error) {
    reportInternalFailure('http-body', error);
    return undefined;
  }
}

/** Build the `HttpError` for a failure, without losing the original cause. */
function makeError(
  message: string,
  request: HttpRequest,
  response: HttpResponse | undefined,
  flags: {
    readonly timedOut: boolean;
    readonly aborted: boolean;
    readonly attempts: number;
    /** Set for a deterministic failure, which must not be retried. */
    readonly nonRetryable?: boolean;
  },
): HttpError {
  const statusCode = response === undefined ? 0 : response.status;
  const error = new Error(message) as {
    -readonly [K in keyof HttpError]: HttpError[K];
  } & { isRetryable?: false };
  error.name = 'HttpError';
  error.request = request;
  if (response !== undefined) error.response = response;
  error.isNetworkError = !flags.timedOut && !flags.aborted && statusCode === 0;
  error.isTimeout = flags.timedOut;
  error.isAbort = flags.aborted;
  error.statusCode = statusCode;
  error.attempts = flags.attempts;
  if (flags.nonRetryable === true) error.isRetryable = false;
  return error;
}

/** Delay helper, used between retries. */
function delay(ms: number): Promise<void> {
  return new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });
}

/**
 * Create a `fetch`-based {@link HttpClient}.
 *
 * @param options - see {@link HttpClientOptions}
 * @returns an {@link HttpClient}
 *
 * @remarks
 * Behaviour worth knowing:
 *
 * - **The timeout is per attempt.** A `retry: 2` call can take three times
 *   `timeoutMs` before it rejects. Retrying is off by default (`retry: 0`).
 * - **Only `0`, `408`, `429` and `5xx` are retried.** See
 *   {@link isRetryableStatus}.
 * - **A missing `fetch` rejects** with an `HttpError` whose `isNetworkError` is
 *   `true`, rather than throwing a `ReferenceError` from a different module.
 * - **`onError` runs before the rejection**, and its own failure is contained, so
 *   a broken reporter cannot change the outcome of the request.
 *
 * @example
 * ```ts
 * import { createFetchHttpClient } from '@codewithrajat/rm-logvault/http';
 * import { captureError } from '@codewithrajat/rm-logvault';
 *
 * const http = createFetchHttpClient({
 *   baseUrl: '/api',
 *   timeoutMs: 10_000,
 *   retry: 1,
 *   onError: (error, context) => captureError(error, context),
 * });
 *
 * const { data } = await http.get<Order[]>('/orders');
 * ```
 */
export function createFetchHttpClient(options: HttpClientOptions = {}): HttpClient {
  const timeoutMs =
    typeof options.timeoutMs === 'number' &&
    Number.isFinite(options.timeoutMs) &&
    options.timeoutMs > 0
      ? options.timeoutMs
      : DEFAULT_HTTP_TIMEOUT_MS;
  const retryCount =
    typeof options.retry === 'number' && Number.isFinite(options.retry) && options.retry > 0
      ? Math.floor(options.retry)
      : 0;
  const retryDelayMs =
    typeof options.retryDelayMs === 'number' &&
    Number.isFinite(options.retryDelayMs) &&
    options.retryDelayMs >= 0
      ? options.retryDelayMs
      : DEFAULT_HTTP_RETRY_DELAY_MS;
  const credentials = options.credentials ?? 'same-origin';
  const bodyMode = options.bodyMode ?? 'json';
  const readAs = options.readAs ?? 'auto';
  const rejectOnHttpError = options.rejectOnHttpError !== false;

  let interceptors: readonly HttpInterceptor[] = [];

  /** Resolve headers for one request: defaults, then provider, then per-request. */
  const resolveHeaders = async (request: HttpRequest): Promise<Record<string, string>> => {
    let provided: Record<string, string> = {};
    if (typeof options.getHeaders === 'function') {
      const fromProvider = await options.getHeaders();
      if (fromProvider !== null && typeof fromProvider === 'object') provided = fromProvider;
    }
    return { ...options.headers, ...provided, ...request.headers };
  };

  /** Serialise the body and report the content type it implies. */
  const serialiseBody = (
    request: HttpRequest,
    headers: Record<string, string>,
  ): { readonly body: BodyInit | undefined; readonly headers: Record<string, string> } => {
    const raw = request.body;
    if (raw === undefined || raw === null) return { body: undefined, headers };

    if (bodyMode === 'raw') {
      return { body: raw as BodyInit, headers };
    }
    if (bodyMode === 'text') {
      const next = { ...headers };
      if (next['Content-Type'] === undefined && next['content-type'] === undefined) {
        next['Content-Type'] = 'text/plain;charset=utf-8';
      }
      return { body: String(raw), headers: next };
    }
    const next = { ...headers };
    if (next['Content-Type'] === undefined && next['content-type'] === undefined) {
      next['Content-Type'] = 'application/json';
    }
    let serialised: string;
    try {
      serialised = JSON.stringify(raw) ?? '';
    } catch (error) {
      // A circular body is a caller bug. It must not produce an unhandled throw
      // from inside the request builder.
      reportInternalFailure('http-body-serialise', error);
      serialised = '';
    }
    return { body: serialised, headers: next };
  };

  /** One attempt, including its own abort timer. */
  const attempt = async (
    request: HttpRequest,
    attemptNumber: number,
  ): Promise<HttpResponse<unknown>> => {
    const fetchImpl = resolveFetch(options.fetchImpl);
    const url = resolveRequestUrl(request.url, options.baseUrl);

    if (fetchImpl === undefined) {
      throw makeError('fetch is not available in this environment', request, undefined, {
        timedOut: false,
        aborted: false,
        attempts: attemptNumber,
      });
    }
    if (url.length === 0) {
      throw makeError('request url is empty', request, undefined, {
        timedOut: false,
        aborted: false,
        attempts: attemptNumber,
      });
    }

    const attemptTimeout =
      typeof request.timeoutMs === 'number' &&
      Number.isFinite(request.timeoutMs) &&
      request.timeoutMs > 0
        ? request.timeoutMs
        : timeoutMs;

    // Reading a caller-supplied signal can throw (a hostile getter), so it happens
    // before the timer is armed — otherwise the timer would leak.
    const externalSignal = request.signal;

    const controller = typeof AbortController !== 'undefined' ? new AbortController() : undefined;
    let timedOut = false;
    const timer =
      controller === undefined
        ? undefined
        : setTimeout(() => {
            timedOut = true;
            try {
              controller.abort();
            } catch {
              // ignore
            }
          }, attemptTimeout);

    // Honour a caller's signal alongside our timeout without taking ownership of
    // it: the listener is removed in the `finally` below.
    const forwardAbort = (): void => {
      try {
        controller?.abort();
      } catch {
        // ignore
      }
    };
    if (externalSignal !== undefined && controller !== undefined) {
      try {
        if (externalSignal.aborted) forwardAbort();
        else externalSignal.addEventListener('abort', forwardAbort, { once: true });
      } catch {
        // A hostile signal is ignored rather than fatal.
      }
    }

    // `0` means "no request was issued", which is how the catch below recognises a
    // deterministic header/serialisation failure. It is set to a real timestamp
    // immediately before `fetch` runs.
    let startedAt = 0;
    try {
      // Header resolution and body serialisation happen INSIDE the guard on
      // purpose. Both are documented ways for the caller to fail the request — a
      // throwing `getHeaders` provider, a body whose serialisation raises — and
      // outside the guard they escaped as the raw thrown value, which `execute`
      // then retried and rethrew without ever constructing an `HttpError`. The
      // contract is that a rejection is always an `HttpError`, and `onError` is
      // only reachable if one is built.
      const headers = await resolveHeaders(request);
      const { body, headers: finalHeaders } = serialiseBody(request, headers);

      startedAt = Date.now();
      const response = await fetchImpl(url, {
        method: request.method,
        headers: finalHeaders,
        ...(body !== undefined ? { body } : {}),
        credentials: request.credentials ?? credentials,
        redirect: 'follow',
        ...(controller !== undefined ? { signal: controller.signal } : {}),
      });

      const durationMs = Date.now() - startedAt;
      const responseHeaders = readHeaders(response.headers);
      const data = await readBody(response, readAs);

      return {
        status: response.status,
        statusText: typeof response.statusText === 'string' ? response.statusText : '',
        headers: responseHeaders,
        data,
        ok: response.ok,
        durationMs,
      };
    } catch (thrown) {
      // A failure we already shaped as an `HttpError` is passed through unchanged;
      // anything else is a header provider or a body serialiser that threw, and it
      // is wrapped so the contract "a rejection is always an HttpError" holds.
      if (thrown instanceof Error && thrown.name === 'HttpError') throw thrown;

      const aborted = externalSignal?.aborted === true;
      // No request was issued for a header/serialisation failure, so `startedAt`
      // never advanced past the preparation phase: it is a deterministic failure
      // and is marked non-retryable rather than retried.
      const fromPreparation = startedAt === 0;
      throw makeError(
        timedOut
          ? `request timed out after ${String(attemptTimeout)}ms`
          : aborted
            ? 'request aborted'
            : thrown instanceof Error && thrown.message.length > 0
              ? thrown.message
              : 'network request failed',
        request,
        undefined,
        { timedOut, aborted, attempts: attemptNumber, nonRetryable: fromPreparation },
      );
    } finally {
      if (timer !== undefined) clearTimeout(timer);
      if (externalSignal !== undefined) {
        try {
          externalSignal.removeEventListener('abort', forwardAbort);
        } catch {
          // ignore
        }
      }
    }
  };

  /** The full pipeline: interceptors, attempts, response interceptors, `onError`. */
  const execute = async <T>(request: HttpRequest): Promise<HttpResponse<T>> => {
    const base: HttpRequest = {
      ...request,
      method: normaliseMethod(request.method),
      headers: request.headers ?? {},
    };

    let prepared: HttpRequest | null = null;
    try {
      prepared = await applyInterceptors(base, interceptors);
    } catch (thrown) {
      // An interceptor threw. Surface it as a contained failure rather than
      // letting an arbitrary value escape as the request's rejection reason.
      const error = makeError(
        thrown instanceof Error ? thrown.message : 'request interceptor failed',
        base,
        undefined,
        { timedOut: false, aborted: false, attempts: 0 },
      );
      await runOnError(error);
      throw error;
    }

    if (prepared === null) {
      const error = makeError('request cancelled by an interceptor', base, undefined, {
        timedOut: false,
        aborted: false,
        attempts: 0,
      });
      await runOnError(error);
      throw error;
    }

    const maxAttempts = 1 + resolveRetry(prepared.retry, retryCount);
    let lastError: HttpError | null = null;
    let response: HttpResponse<unknown> | null = null;

    for (let attemptNumber = 1; attemptNumber <= maxAttempts; attemptNumber += 1) {
      try {
        response = await attempt(prepared, attemptNumber);
      } catch (thrown) {
        const failure = thrown as HttpError;
        lastError = failure;
        // A deterministic failure — a throwing header provider, an unserialisable
        // body — raises the same throw every time, so retrying it only multiplies
        // the work. Everything else is a transport failure with no status to
        // classify, and `0` is always retryable.
        const deterministic = (failure as { isRetryable?: unknown }).isRetryable === false;
        if (attemptNumber < maxAttempts && !deterministic) {
          await delay(backoffFor(attemptNumber, retryDelayMs));
          continue;
        }
        await runOnError(failure);
        throw failure;
      }

      // A non-ok response is only an error when the caller asked for that. When
      // `rejectOnHttpError` is false the response *is* the result, so there is
      // nothing to retry — `retry` applies to failures that reject.
      if (response.ok || !rejectOnHttpError) break;

      const failure = makeError(
        `request failed with status ${String(response.status)}`,
        prepared,
        response,
        { timedOut: false, aborted: false, attempts: attemptNumber },
      );
      lastError = failure;

      if (attemptNumber < maxAttempts && isRetryableStatus(response.status)) {
        await delay(backoffFor(attemptNumber, retryDelayMs));
        continue;
      }
      await runOnError(failure);
      throw failure;
    }

    if (response === null) {
      const failure =
        lastError ??
        makeError('request failed', prepared, undefined, {
          timedOut: false,
          aborted: false,
          attempts: maxAttempts,
        });
      await runOnError(failure);
      throw failure;
    }

    // Response interceptors run last, on the success path only.
    let final = response as HttpResponse<T>;
    for (const interceptor of interceptors) {
      const hook = interceptor.onResponse;
      if (typeof hook !== 'function') continue;
      try {
        const replaced = await hook(final, prepared);
        if (replaced !== null && typeof replaced === 'object') final = replaced;
      } catch (error) {
        reportInternalFailure('http-interceptor-response', error);
      }
    }
    return final;
  };

  /** Deliver a failure to the interceptors and `onError`, containing every throw. */
  const runOnError = async (error: HttpError): Promise<void> => {
    for (const interceptor of interceptors) {
      const hook = interceptor.onError;
      if (typeof hook !== 'function') continue;
      try {
        await hook(error);
      } catch (failure) {
        reportInternalFailure('http-interceptor-error', failure);
      }
    }
    const onError = options.onError;
    if (typeof onError !== 'function') return;
    try {
      onError(error, buildHttpErrorContext(error));
    } catch (failure) {
      reportInternalFailure('http-on-error', failure);
    }
  };

  return {
    request: execute,

    get: <T>(url: string, requestOptions?: Partial<HttpRequest>): Promise<HttpResponse<T>> =>
      execute<T>({ ...requestOptions, url, method: 'GET' }),

    post: <T>(
      url: string,
      body?: unknown,
      requestOptions?: Partial<HttpRequest>,
    ): Promise<HttpResponse<T>> => execute<T>({ ...requestOptions, url, method: 'POST', body }),

    put: <T>(
      url: string,
      body?: unknown,
      requestOptions?: Partial<HttpRequest>,
    ): Promise<HttpResponse<T>> => execute<T>({ ...requestOptions, url, method: 'PUT', body }),

    patch: <T>(
      url: string,
      body?: unknown,
      requestOptions?: Partial<HttpRequest>,
    ): Promise<HttpResponse<T>> => execute<T>({ ...requestOptions, url, method: 'PATCH', body }),

    delete: <T>(url: string, requestOptions?: Partial<HttpRequest>): Promise<HttpResponse<T>> =>
      execute<T>({ ...requestOptions, url, method: 'DELETE' }),

    setInterceptors: (next: readonly HttpInterceptor[]): void => {
      interceptors = Array.isArray(next) ? [...next] : [];
    },

    getInterceptors: (): readonly HttpInterceptor[] => interceptors,
  };
}

/** Keep only the methods the contract declares. */
function normaliseMethod(method: HttpMethod): HttpMethod {
  const upper = typeof method === 'string' ? method.toUpperCase() : '';
  switch (upper) {
    case 'GET':
    case 'POST':
    case 'PUT':
    case 'PATCH':
    case 'DELETE':
    case 'HEAD':
    case 'OPTIONS':
      return upper;
    default:
      return 'GET';
  }
}

/** Resolve the retry count for one request. */
function resolveRetry(perRequest: number | undefined, fallback: number): number {
  if (typeof perRequest === 'number' && Number.isFinite(perRequest) && perRequest >= 0) {
    return Math.floor(perRequest);
  }
  return fallback;
}

/** Exponential backoff, bounded so a mis-set retry delay cannot hang a request. */
function backoffFor(attemptNumber: number, base: number): number {
  const exponent = Math.min(attemptNumber - 1, 6);
  return Math.min(base * 2 ** exponent, 30_000);
}
